import{_ as t,a,b as o}from"./chunks/exprx.Cl_2Ow3E.js";import{_ as i}from"./chunks/sh5.BlogWVwG.js";import{_ as r,c as n,o as l,ae as s}from"./chunks/framework.BrQRMotl.js";const k=JSON.parse(`{"title":"Conductor's Wand","description":"","frontmatter":{},"headers":[],"relativePath":"manual/conductor_wand.md","filePath":"manual/conductor_wand.md"}`),d={name:"manual/conductor_wand.md"};function c(h,e,u,p,g,m){return l(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="conductor-s-wand" tabindex="-1">Conductor&#39;s Wand <a class="header-anchor" href="#conductor-s-wand" aria-label="Permalink to &quot;Conductor&#39;s Wand&quot;">​</a></h1><p>The <strong>Conductor&#39;s Wand</strong> is a tool designed for large-scale Note Block projects, allowing players to select regions like in WorldEdit and batch-edit properties of all Extended Note Blocks within the selection.</p><h2 id="basic-operations" tabindex="-1">Basic Operations <a class="header-anchor" href="#basic-operations" aria-label="Permalink to &quot;Basic Operations&quot;">​</a></h2><h3 id="_1-region-selection" tabindex="-1">1. Region Selection <a class="header-anchor" href="#_1-region-selection" aria-label="Permalink to &quot;1. Region Selection&quot;">​</a></h3><ul><li><strong>Set Point 1 (Pos1)</strong>: Hold the wand and <strong>Left Click</strong> a block. <img src="'+t+'" alt="Pos1"></li><li><strong>Set Point 2 (Pos2)</strong>: Hold the wand and <strong>Right Click</strong> a block. <img src="'+a+'" alt="Pos2"></li><li>Once the selection is complete, the screen will display the selected range.</li><li>Hold the Backspace key to cancel the selection.</li></ul><h3 id="_2-open-editor-interface" tabindex="-1">2. Open Editor Interface <a class="header-anchor" href="#_2-open-editor-interface" aria-label="Permalink to &quot;2. Open Editor Interface&quot;">​</a></h3><ul><li>After selecting two points, press the Enter key to open the Conductor interface. <img src="'+i+'" alt="ConductorScreen"><img src="'+o+'" alt="ExprX"></li></ul><h2 id="batch-editing-features" tabindex="-1">Batch Editing Features <a class="header-anchor" href="#batch-editing-features" aria-label="Permalink to &quot;Batch Editing Features&quot;">​</a></h2><p>The interface lists all editable parameters of the Extended Note Block. Each parameter has a <strong>Mode Switch Button</strong> next to it:</p><h3 id="edit-modes-explained" tabindex="-1">Edit Modes Explained <a class="header-anchor" href="#edit-modes-explained" aria-label="Permalink to &quot;Edit Modes Explained&quot;">​</a></h3><ul><li><strong>Keep (K)</strong>: Does not modify this parameter, keeping the block&#39;s original value.</li><li><strong>Set (=)</strong>: Sets this parameter for all blocks in the selection to the input value.</li><li><strong>Add (+)</strong>: Adds the input value to the block&#39;s original value (e.g., raise all notes by an octave +12).</li><li><strong>Subtract (-)</strong>: Subtracts the input value from the original value.</li><li><strong>Multiply (x)</strong> / <strong>Divide (/)</strong>: Scales the parameter by a factor (commonly used for percentage adjustments of velocity or delay).</li></ul><h3 id="supported-parameters" tabindex="-1">Supported Parameters <a class="header-anchor" href="#supported-parameters" aria-label="Permalink to &quot;Supported Parameters&quot;">​</a></h3><ul><li>Note (Pitch)</li><li>Velocity</li><li>Sustain</li><li>Delay</li><li>Fade In/Out</li><li>Properties in Advanced Mode</li></ul><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to &quot;Practical Tips&quot;">​</a></h2><ol><li><strong>Quick Transposition</strong>: After selecting a musical section, use the &quot;Add&quot; mode and input <code>12</code> or <code>-12</code> to quickly raise or lower it by an octave.</li><li><strong>Gradient Dynamics</strong>: Set a base velocity uniformly, then refine it with envelopes in Advanced Mode.</li><li><strong>Global Alignment</strong>: If a section is rushing within a beat, use the &quot;Add&quot; mode to add a uniform positive deviation to the Delay.</li></ol>',15)])])}const P=r(d,[["render",c]]);export{k as __pageData,P as default};
